import { RamWorksMemoryStart } from "../common/utility"
import { addressGetTable, RamWorksBankGet, RamWorksMaxBank, memory, getAuxCardEnabled } from "./memory"
import { SWITCHES } from "./softswitches"

const getBackingLocation = (address: number) => {
  if (address >= 0xC000) return { space: "system" as const }
  const offset = addressGetTable[address >>> 8] + (address & 0xFF)
  if (offset < 0x10000) return { space: "main" as const }
  // Past the last bank is the stand-in for a bank with no memory behind it.
  if (offset >= RamWorksMemoryStart && offset < RamWorksMemoryStart + (RamWorksMaxBank + 1) * 0x10000) {
    return {
      space: "aux" as const,
      auxBank: Math.floor((offset - RamWorksMemoryStart) / 0x10000),
    }
  }
  return { space: "system" as const }
}

const getEffectiveSegments = (
  address: number,
  length: number,
  space: MemorySpace,
  auxBank: number,
) => {
  const segments: MemoryViewSegment[] = []
  for (let current = address; current < address + length; current++) {
    const location = space === "active"
      ? getBackingLocation(current)
      : space === "aux"
        ? { space, auxBank }
        : { space }
    const previous = segments.at(-1)
    if (
      previous
      && previous.address + previous.length === current
      && previous.space === location.space
      && previous.auxBank === location.auxBank
    ) {
      previous.length++
    } else {
      segments.push({address: current, length: 1, ...location})
    }
  }
  return segments
}

export const resolveMemoryRangeRequest = (request: MemoryViewRequest) => {
  const {address, length, space} = request
  if (!Number.isInteger(address) || address < 0 || address > 0xFFFF) {
    throw new Error("Memory address must be between $0000 and $FFFF")
  }
  if (!Number.isInteger(length) || length < 1 || address + length > 0x10000) {
    throw new Error("Memory range must fit within $0000-$FFFF")
  }
  if (!(["active", "main", "aux"] as MemorySpace[]).includes(space)) {
    throw new Error("Unknown memory space")
  }
  if (request.auxBank !== undefined && space !== "aux") {
    throw new Error("Auxiliary bank is valid only for auxiliary memory")
  }
  if (space !== "active" && address + length > 0xC000) {
    throw new Error("Physical memory range must fit within $0000-$BFFF")
  }
  const selectedAuxBank = RamWorksBankGet()
  const auxBank = request.auxBank ?? selectedAuxBank
  if (space === "aux") {
    if (!getAuxCardEnabled()) throw new Error("Auxiliary memory is not configured")
    if (!Number.isInteger(auxBank) || auxBank < 0 || auxBank > RamWorksMaxBank) {
      throw new Error(`Auxiliary bank must be between 0 and ${RamWorksMaxBank}`)
    }
  }

  return {
    address,
    length,
    space,
    requestedAuxBank: request.auxBank ?? null,
    auxBank,
  }
}

export const getMemoryView = (request: MemoryViewRequest): MemoryView => {
  const {address, length, space, requestedAuxBank, auxBank} = resolveMemoryRangeRequest(request)

  let bytes: Uint8Array
  if (space === "active") {
    bytes = new Uint8Array(length)
    for (let index = 0; index < length; index++) {
      const current = address + index
      const offset = addressGetTable[current >>> 8] + (current & 0xFF)
      bytes[index] = memory[offset]
    }
  } else {
    const offset = space === "main" ? address : RamWorksMemoryStart + auxBank * 0x10000 + address
    bytes = memory.slice(offset, offset + length)
  }

  const effectiveSegments = getEffectiveSegments(address, length, space, auxBank)
  return {
    address,
    length,
    requestedSpace: space,
    requestedAuxBank,
    effectiveAuxBank: effectiveSegments.some((segment) => segment.space === "aux")
      ? auxBank
      : null,
    effectiveSegments,
    mapping: {
      RAMRD: SWITCHES.AUXRAMREAD.isSet,
      RAMWRT: SWITCHES.AUXRAMWRITE.isSet,
      ALTZP: SWITCHES.ALTZP.isSet,
      "80STORE": SWITCHES.STORE80.isSet,
      PAGE2: SWITCHES.PAGE2.isSet,
      HIRES: SWITCHES.HIRES.isSet,
    },
    bytes,
  }
}

export const createMemoryPredicateMatcher = (predicate: MemoryPredicate) => {
  const pattern = predicate?.bytes
  if (!Array.isArray(pattern) || pattern.length < 1 || pattern.length > 32
    || pattern.some((byte) => !Number.isInteger(byte) || byte < 0 || byte > 0xFF)) {
    throw new Error("Memory predicate must contain 1 to 32 byte values")
  }
  const mask = predicate.mask ?? pattern.map(() => 0xFF)
  if (!Array.isArray(mask) || mask.length !== pattern.length
    || mask.some((byte) => !Number.isInteger(byte) || byte < 0 || byte > 0xFF)) {
    throw new Error("Memory predicate mask must match the byte pattern")
  }
  const resolved = resolveMemoryRangeRequest({
    address: predicate.address,
    length: pattern.length,
    space: predicate.space,
    auxBank: predicate.auxBank,
  })
  const checks = pattern.flatMap((byte, index) => mask[index] === 0
    ? []
    : [{index, mask: mask[index], expected: byte & mask[index]}])
  const physicalOffset = resolved.space === "main"
    ? resolved.address
    : resolved.space === "aux"
      ? RamWorksMemoryStart + resolved.auxBank * 0x10000 + resolved.address
      : null

  const readByte = (index: number) => {
    const address = resolved.address + index
    return memory[physicalOffset === null
      ? addressGetTable[address >>> 8] + (address & 0xFF)
      : physicalOffset + index]
  }
  return Object.assign(() => {
    for (const check of checks) {
      if ((readByte(check.index) & check.mask) !== check.expected) return false
    }
    return true
  }, {read: () => pattern.map((_, index) => readByte(index))})
}

export const findMemory = (request: MemorySearchRequest): MemorySearchResult => {
  const {bytes: pattern, maxMatches = 32} = request
  if (!Array.isArray(pattern) || pattern.length < 1 || pattern.length > 32
    || pattern.some((byte) => !Number.isInteger(byte) || byte < 0 || byte > 0xFF)) {
    throw new Error("Memory pattern must contain 1 to 32 byte values")
  }
  if (!Number.isInteger(maxMatches) || maxMatches < 1 || maxMatches > 64) {
    throw new Error("Maximum matches must be between 1 and 64")
  }

  const {bytes, ...view} = getMemoryView(request)
  const matches: number[] = []
  let totalMatchCount = 0
  for (let offset = 0; offset + pattern.length <= bytes.length; offset++) {
    if (pattern.every((byte, index) => bytes[offset + index] === byte)) {
      totalMatchCount++
      if (matches.length < maxMatches) matches.push(request.address + offset)
    }
  }
  return {
    ...view,
    matches,
    totalMatchCount,
    truncated: totalMatchCount > matches.length,
  }
}
